import{_ as o,l,o as a,c as i,v as t,p as s,x as n,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"线段树","description":"","frontmatter":{"title":"线段树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/segment-tree.md","filePath":"cs/segment-tree.md","lastUpdated":1789023840000}'),m={name:"cs/segment-tree.md"};function h(_,e,B,E,u,A){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="线段树" tabindex="-1">线段树 <a class="header-anchor" href="#线段树" aria-label="Permalink to &quot;线段树&quot;">​</a></h1><div class="epigraph"><p>把下标区间递归对半切开，每个节点存自己那段的聚合；查询把目标区间拆成 $O(\\log n)$ 个已有节点。</p><footer>—— 据 Bentley, Solutions to Klee&#39;s rectangle problems, 1977；Cormen, Leiserson, Rivest and Stein；Sedgewick and Wayne 整理</footer></div><p><a href="/cs/fenwick-tree">上一课</a>把加法前缀收成 \\(n\\) 格的二进制索引。最值、任意结合运算、以及「查询任意 \\([l,r]\\) 而不先转前缀」并不贴 Fenwick 的 lowbit 形状。本课不重讲 \\(\\mathrm{lowbit}\\)。缺口是线段树：一棵固定形状的区间二叉树，单点修改与区间查询 \\(O(\\log n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态稀疏表不能改；Fenwick 的区间切法绑在二进制进位上。需要：节点对应 \\([L,R]\\)，左右孩子对半，叶对应单点。每个节点存 \\(\\mathrm{op}(A[L..R])\\)，\\(\\mathrm{op}\\) 可结合。查询 \\([l,r]\\)：从根往下，与当前节点区间全含则返回该节点值，相交则左右合并，不相交则单位元。缺口是<strong>把任意区间规范成树上 \\(O(\\log n)\\) 个不相交节点</strong>。</p><p>单点改：只更新根到该叶的路径，自底向上重算。</p><p><span class="marginnote">Bentley 的线段树原用于几何「线段与扫描线」；竞赛与数据库里常指这一棵下标区间树。不要与后课几何 interval tree 混名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建树 \\(\\Theta(n)\\)：叶抄 \\(A\\)，内部 \\(\\mathrm{op}(左,右)\\)。堆式下标：根 \\(1\\)，左 \\(2u\\)，右 \\(2u+1\\)，数组约 \\(4n\\)。查询与修改都沿高度 \\(O(\\log n)\\)。单位元：加法是 \\(0\\)，最小值是 \\(+\\infty\\)，须在合同里写明。</p>',9)),(a(),s(c,null,{default:n(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%20%5B1%2C%20n%5D%22%5D%20--%3E%20L%5B%22%E5%B7%A6%E5%8D%8A%22%5D%0A%20%20ROOT%20--%3E%20R%5B%22%E5%8F%B3%E5%8D%8A%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20%5Bl%2C%20r%5D%22%5D%20--%3E%20DISJ%5B%22O(log%20n)%20%E4%B8%AA%E4%B8%8D%E7%9B%B8%E4%BA%A4%E8%8A%82%E7%82%B9%22%5D%0A%20%20DISJ%20--%3E%20OP%5B%22%E6%8C%89%E7%BB%93%E5%90%88%E5%BE%8B%E5%90%88%E5%B9%B6%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与稀疏表：线段树可改，查询 \\(O(\\log n)\\) 不是 \\(O(1)\\)。与 Fenwick：线段树对 \\(\\mathrm{op}\\) 只要求结合，不要求 lowbit 友好的前缀分解。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>任意 \\([l,r]\\) 在对半切分下最多被切成每层常数个片段，故节点数 \\(O(\\log n)\\)。修改只脏一条叶到根的链，因为兄弟子树的聚合未变。这与<a href="/cs/bst">BST</a> 不同：这里树形由 \\(n\\) 固定，不随键旋转；下标就是键。</p><p>递归实现注意边界 \\(L=R\\) 为叶。迭代版按位拆区间，本课不要求写完。空间 \\(O(n)\\)，常数大于 Fenwick。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只钉点修、区间查询。区间加仍要扫叶则退回 \\(\\Theta(n)\\)——下一课懒标记把更新停在覆盖节点上。可持久化、动态开点也不在本课。\\(\\mathrm{op}\\) 必须可结合；不可结合就不要放进节点。</p><p>后课默认：静态结合区间可更新时，线段树是默认树。成段修改用懒标记。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线段树：对半区间树，点修与区间查询 \\(O(\\log n)\\)。</li><li>运算可结合即可；形状由 \\(n\\) 固定。</li><li>区间更新留给懒标记。</li><li>出处：Bentley, 1977；Cormen et al.；Sedgewick and Wayne。</li></ul>',9))])}const T=o(m,[["render",h]]);export{g as __pageData,T as default};
